heuristicScanPortsNative.script:
param(
  [string]$target
)

try {
  $ports = @(21,22,23,25,80,443,3389,445,3306,5432,8080)
  $results = @()
  foreach ($port in $ports) {
    $open = $false
    try {
      $client = New-Object System.Net.Sockets.TcpClient
      $connectTask = $client.ConnectAsync($target, $port)
      if ($connectTask.Wait(300)) {
        $open = $client.Connected
      }
      $client.Close()
    } catch {
      $open = $false
    }
    $results += [PSCustomObject]@{ ip = $target; port = $port; open = $open }
  }
  $results | ConvertTo-Json -Compress
} catch {
  Write-Output "[]"
}
